535	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
536	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
537	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
538	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
539	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
540	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
541	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
542	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
543		handoverID = clean(handoverID)
544		itemID = clean(itemID)
545		operator = clean(operator)
546		reason = clean(reason)
547		trackingNote = clean(trackingNote)
548		nextFollowOwner = clean(nextFollowOwner)
549	
550		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
551			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
552		}
553		if err := requireNonEmpty("操作人", operator); err != nil {
554			return Handover{}, err
555		}
556	
557		var result Handover
558		err := svc.store.mutate(func(d *Data) error {
559			h, _ := findHandover(d, handoverID)
560			if h == nil {
561				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
562			}
563			e, _ := findEntry(h, itemID)
564			if e == nil {
565				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
566			}
567			if e.Status.Received() {
568				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
569					ErrHandoverState, e.ItemID, e.Status.Label())
570			}
571			if e.Status == EntryReturned {
572				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
573				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
574				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
575				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
576					ErrHandoverState, e.ItemID, h.ID)
577			}
578			switch action {
579			case ActionReturn:
580				if err := requireNonEmpty("退回原因", reason); err != nil {
581					return err
582				}
583			case ActionTrack:
584				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
585					return err
586				}
587				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
588					return err
589				}
590			}
591	
592			now := svc.now()
593			switch action {
594			case ActionConfirm:
595				e.Status = EntryConfirmed
596			case ActionTrack:
597				e.Status = EntryTracking
598				e.TrackingNote = trackingNote
599				e.FollowOwner = nextFollowOwner
600			case ActionReturn:
601				e.Status = EntryReturned
602				e.Rounds = append(e.Rounds, ReturnRound{
603					Seq:            len(e.Rounds) + 1,
604					ReturnedAt:     now,
605					ReturnOperator: operator,
606					Reason:         reason,
607				})
608			}
609			e.Operator = operator
610			e.ProcessedAt = &now
611	
612			if action != ActionReturn {
613				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
614				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
615					it.CurrentShiftID = h.ToShiftID
616					if !contains(it.ShiftIDs, h.ToShiftID) {
617						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
618					}
619					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
620					if action == ActionTrack {
621						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
622						it.FollowOwner = nextFollowOwner
623					}
624					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
625				}
626			}
627	
628			if h.Completed() {
629				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
630				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
631				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
632				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
633				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
634				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
635				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
636				// 项无法再处理，完成时间不会被改写。
637				h.CompletedAt = &now
638			}
639			result = *h
640			return nil
641		})
642		return result, err
643	}
644	
645	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
646	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
647	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
648	
649	func contains(xs []string, x string) bool {
650		for _, v := range xs {
651			if v == x {
652				return true
653			}
654		}
655		return false
656	}
657	
658	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
659	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
660	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
661	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
662	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
663	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
664	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
665		handoverID = clean(handoverID)
666		itemID = clean(itemID)
667		operator = clean(operator)
668		supplement = clean(supplement)
669		if err := requireNonEmpty("操作人", operator); err != nil {
670			return Handover{}, err
671		}
672		if err := requireNonEmpty("补充说明", supplement); err != nil {
673			return Handover{}, err
674		}
675	
676		var result Handover
677		err := svc.store.mutate(func(d *Data) error {
678			h, _ := findHandover(d, handoverID)
679			if h == nil {
680				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
681			}
682			e, _ := findEntry(h, itemID)
683			if e == nil {
684				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
685			}
686			if e.Status != EntryReturned {
687				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
688					ErrHandoverState, e.ItemID, e.Status.Label())
689			}
690			if len(e.Rounds) == 0 {
691				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
692			}
693			round := &e.Rounds[len(e.Rounds)-1]
694			if round.ResubmittedAt != nil {
695				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
696			}
697			now := svc.now()
698			round.Supplement = supplement
699			round.SupplementOperator = operator
700			round.SupplementAt = &now
701			round.ResubmittedAt = &now
702			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
703			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
704			e.Status = EntryPending
705			e.Operator = ""
706			e.ProcessedAt = nil
707			result = *h
708			return nil
709		})
710		return result, err
711	}
712	
713	// GetShift 按编号查询班次。
714	func (svc *Service) GetShift(id string) (Shift, error) {
715		sh, _ := findShift(&svc.store.data, clean(id))
716		if sh == nil {
717			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
718		}
719		return *sh, nil
720	}
721	
722	// ListShifts 返回全部班次，按编号排序。
723	func (svc *Service) ListShifts() []Shift {
724		out := append([]Shift(nil), svc.store.data.Shifts...)
725		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
726		return out
727	}
728	
729	// GetItem 按稳定编号查询事项。
730	func (svc *Service) GetItem(id string) (Item, error) {
731		it, _ := findItem(&svc.store.data, clean(id))
732		if it == nil {
733			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
734		}
735		return *it, nil
736	}
737	
738	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
739	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
740	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
741	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
742	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
743	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
744	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
745	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
746	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
747	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
748	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
749	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
750	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
751	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
752	// 不改变事项、交接进度或班次结束时记录。
753	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
754		itemID = clean(itemID)
755		d := &svc.store.data
756		it, _ := findItem(d, itemID)
757		if it == nil {
758			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
759		}
760		j := ItemJourney{Item: *it}
761	
762		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
763		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
764		// 该轮重新提交、后续处理）。
765		type keyedEvent struct {
766			ev    JourneyEvent
767			group string // "" 表示事项自身事件，否则为交接编号
768			ord   int    // 同一（时刻、分组）内的先后
769		}
770		var events []keyedEvent
771		seq := 0
772		add := func(ev JourneyEvent, group string) {
773			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
774			seq++
775		}
776	
777		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
778		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
779		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
780		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
781		merge := newReceivedMerge(it.Events)
782	
783		hs := append([]Handover(nil), d.Handovers...)
784		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
785		for k := range hs {
786			h := &hs[k]
787			e, _ := findEntry(h, itemID)
788			if e == nil {
789				continue
790			}
791			j.HasHandovers = true
792			j.Results = append(j.Results, EntryView{
793				HandoverID: h.ID,
794				FromShift:  h.FromShiftID,
795				ToShift:    h.ToShiftID,
796				Entry:      *e,
797			})
798	
799			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
800			add(JourneyEvent{
801				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
802				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
803			}, h.ID)
804			for _, r := range e.Rounds {
805				add(JourneyEvent{
806					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
807					Kind: "return", Operator: r.ReturnOperator,
808					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
809					RoundSeq: r.Seq, Reason: r.Reason,
810				}, h.ID)
811				if r.ResubmittedAt != nil {
812					add(JourneyEvent{
813						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
814						Kind: "resubmit", Operator: r.SupplementOperator,
815						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
816						RoundSeq: r.Seq, Supplement: r.Supplement,
817						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
818					}, h.ID)
819				}
820			}
821			if e.Status == EntryReturned && len(e.Rounds) == 0 {
822				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
823				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
824				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
825				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
826				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
827				ev := JourneyEvent{
828					Kind: "return-incomplete", Operator: e.Operator,
829					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
830					HistoryIncomplete: true,
831				}
832				if validProcessedAt(e.ProcessedAt) {
833					ev.At, ev.TimeKnown = *e.ProcessedAt, true
834				}
835				add(ev, h.ID)
836			}
837			if e.Status.Received() {
838				rcpt := receiptFromEntry(h, e)
839				ev := JourneyEvent{
840					Kind: rcpt.kind, Operator: e.Operator,
841					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
842					TrackingNote: e.TrackingNote,
843					// 继续跟踪当时指定的后续负责人取自交接记录快照，
844					// 之后修改事项负责人不改变这里的历史值。
845					FollowOwner: e.FollowOwner,
846				}
847				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
848				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
849				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
850				if rcpt.timeKnown {
851					ev.At, ev.TimeKnown = rcpt.at, true
852				}
853				add(ev, h.ID)
854				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
855				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
856				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
857				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
858				merge.consider(rcpt)
859			}
860		}
861	
862		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
863		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
864		for i, iev := range it.Events {
865			if iev.Kind == "received" && merge.isUsed(i) {
866				continue
867			}
868			add(JourneyEvent{
869				At: iev.At, TimeKnown: !iev.At.IsZero(),
870				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
871			}, "")
872		}
873	
874		sort.SliceStable(events, func(i, k int) bool {
875			a, b := events[i], events[k]
876			if a.ev.TimeKnown != b.ev.TimeKnown {
877				return a.ev.TimeKnown
878			}
879			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
880				return a.ev.At.Before(b.ev.At)
881			}
882			if a.group != b.group {
883				return a.group < b.group
884			}
885			return a.ord < b.ord
886		})
887		for _, ke := range events {
888			j.Events = append(j.Events, ke.ev)
889		}
890		return j, nil
891	}
892	
893	// GetHandover 按编号查询交接。
894	func (svc *Service) GetHandover(id string) (Handover, error) {
895		h, _ := findHandover(&svc.store.data, clean(id))
896		if h == nil {
897			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
898		}
899		return *h, nil
900	}
901	
902	// ListHandovers 返回全部交接记录，按编号排序。
903	func (svc *Service) ListHandovers() []Handover {
904		out := append([]Handover(nil), svc.store.data.Handovers...)
905		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
906		return out
907	}
908	
909	// OverlapNotes 返回涉及指定班次的全部重叠说明。
910	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
911		shiftID = clean(shiftID)
912		out := []OverlapNote{}
913		for _, n := range svc.store.data.Notes {
914			if n.ShiftA == shiftID || n.ShiftB == shiftID {
915				out = append(out, n)
916			}
917		}
918		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
919		return out
920	}
921	
922	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
923	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
924	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
925	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
926		shiftID = clean(shiftID)
927		d := &svc.store.data
928		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
929		sh, _ := findShift(d, shiftID)
930		if sh == nil {
931			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
932		}
933		rep.Shift = *sh
934	
935		for _, n := range d.Notes {
936			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
937				rep.OverlapNotes = append(rep.OverlapNotes, n)
938			}
939		}
940		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
941	
942		switch {
943		case !sh.Closed:
944			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
945			rep.Items = currentItemsOfShift(d, sh.ID)
946		case sh.CloseRecord != nil:
947			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
948			rep.ItemsAtClose = true
949			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
950			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
951			for _, s := range rep.CloseItems {
952				if it, _ := findItem(d, s.ItemID); it != nil {
953					rep.LatestItems[s.ItemID] = *it
954				}
955			}
956		default:
957			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
958			rep.HistoryIncomplete = true
959			rep.Items = currentItemsOfShift(d, sh.ID)
960		}
961		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
962	
963		for i := range d.Handovers {
964			h := &d.Handovers[i]
965			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
966			if !involved {
967				continue
968			}
969			if h.FromShiftID == sh.ID {
970				cp := *h
971				rep.Outgoing = &cp
972			}
973			if h.ToShiftID == sh.ID {
974				rep.Incoming = append(rep.Incoming, *h)
975			}
976			for j := range h.Entries {
977				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
978					HandoverID: h.ID,
979					FromShift:  h.FromShiftID,
980					ToShift:    h.ToShiftID,
981					Entry:      h.Entries[j],
982				})
983			}
984		}
985		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
986		for k := range rep.Results {
987			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
988		}
989		return rep, nil
990	}
